/**
 * @name Path traversal in file operations
 * @description User-controlled data flowing to file operations without validation may allow path traversal attacks
 * @kind path-problem
 * @problem.severity warning
 * @id py/path-traversal-anyio
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fsa |
      sink = fsa.getAPathArgument()
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "File path may be controlled by user input from $@.", source.getNode(), "this source"

/**
 * @name Insecure deserialization with pickle
 * @description Using pickle to deserialize untrusted data can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/insecure-pickle-deserialization
 * @tags security
 *       external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs
import semmle.python.dataflow.new.RemoteFlowSources

module PickleDeserializationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pickle").getMember(["loads", "load"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PickleDeserializationFlow = TaintTracking::Global<PickleDeserializationConfig>;
import PickleDeserializationFlow::PathGraph

from PickleDeserializationFlow::PathNode source, PickleDeserializationFlow::PathNode sink
where PickleDeserializationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Pickle deserialization of untrusted data from $@.", source.getNode(), "user-controlled source"

/**
 * @name Uncontrolled resource allocation
 * @description Allocating resources based on untrusted input without limits can lead to DoS
 * @kind path-problem
 * @problem.severity warning
 * @id py/uncontrolled-allocation
 * @tags security
 *       external/cwe/cwe-770
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module ResourceAllocationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // Memory allocation through bytearray, bytes, list multiplication
      call = API::builtin(["bytearray", "bytes"]).getACall() and
      sink = call.getArg(0)
      or
      // Buffer size allocations
      call.getFunction().asExpr().(Attribute).getName() in ["read", "recv", "recvfrom"] and
      sink = call.getArg(0)
      or
      // Range/list comprehension with size parameter
      call = API::builtin("range").getACall() and
      sink = call.getArg(0)
    )
  }
}

module ResourceAllocationFlow = TaintTracking::Global<ResourceAllocationConfig>;
import ResourceAllocationFlow::PathGraph

from ResourceAllocationFlow::PathNode source, ResourceAllocationFlow::PathNode sink
where ResourceAllocationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Resource allocation based on untrusted input from $@.", source, "user input"
